class RubyRisksCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
        # We'll store state in self._model
        if not hasattr(self._model, 'rr_state'):
            self._model.rr_state = {}

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        # total_rubies: int, current_turn: int, feedback: List[int], boxes: int
        total_rubies, current_turn, feedback, boxes = data
        n_turns = len(feedback)
        box_idx = n_turns  # Box we're working on (0-indexed)

        # Restore search state from model
        rr_state = self._model.rr_state
        # We'll store per-box searching interval (lo, hi), and probe amount
        if 'box_search' not in rr_state:
            rr_state['box_search'] = {}
        box_search = rr_state['box_search']

        # If box_idx >= boxes, there's nothing left
        if box_idx >= boxes:
            rubies_requested = 1  # Just request 1, should not matter
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=rubies_requested, type='custom')]
            )

        # Compute how many rubies remain 
        collected = sum(feedback)
        rubies_left = total_rubies - collected
        # For last box, we might as well request all remaining
        if box_idx == boxes - 1:
            rubies_requested = rubies_left if rubies_left > 0 else 1
            return Info(
                sender=self.__class__.__name__,
                receiver=message.sender,
                difficulty=message.difficulty,
                message=[BaseMessageDataType(data=rubies_requested, type='custom')]
            )

        # State per box:
        if box_idx not in box_search:
            # New box: initialize probe state
            box_search[box_idx] = {
                'stage': 'exp',         # 'exp' or 'bin'
                'last_lo': 0,           # Largest successful request
                'last_hi': None,        # Smallest failed request
                'probe': 1
            }
        state = box_search[box_idx]

        # Assess previous turn for this box
        if n_turns > 0:
            last_result = feedback[-1]
            # Did we fail (get 0)?
            if state['stage'] == 'exp':
                if last_result > 0:
                    # Previous probe worked, increase exponentially
                    state['last_lo'] = state['probe']
                    state['probe'] *= 2
                    # But cap probe at remaining rubies! (or total_rubies)
                    max_possible = min(total_rubies, rubies_left)
                    state['probe'] = min(state['probe'], max_possible)
                else:
                    # Previous probe failed, start binary search
                    state['last_hi'] = state['probe']
                    state['stage'] = 'bin'
                    # Initial bin lower bound
                    if state['last_lo'] == 0:
                        state['next'] = 1
                    else:
                        state['next'] = (state['last_lo'] + state['last_hi']) // 2
            elif state['stage'] == 'bin':
                prev_req = state.get('last_request', 1)
                if last_result == 0:
                    state['last_hi'] = prev_req
                else:
                    state['last_lo'] = prev_req
                # If hi - lo == 1, we've found the count
                if state['last_hi'] is not None and state['last_lo'] is not None and state['last_hi'] - state['last_lo'] == 1:
                    # This is the true count of box rubies
                    state['final'] = state['last_lo']
                    state['stage'] = 'done'
                else:
                    # Next probe
                    if state['last_hi'] is None:
                        hi = state['probe']
                    else:
                        hi = state['last_hi']
                    if state['last_lo'] is None:
                        lo = 0
                    else:
                        lo = state['last_lo']
                    state['next'] = (lo + hi) // 2

        # Now pick next request
        if state['stage'] == 'exp':
            rubies_requested = state['probe']
        elif state['stage'] == 'bin':
            rubies_requested = state.get('next', 1)
        elif state['stage'] == 'done':
            rubies_requested = state['final']
        else:
            rubies_requested = 1  # Fallback
        # Don't ask for more than remaining
        rubies_requested = min(rubies_requested, rubies_left)
        if rubies_requested <= 0:
            rubies_requested = 1  # failsafe
        # For next turn: store requested for use in feedback parsing
        state['last_request'] = rubies_requested

        # Store updated search state
        rr_state['box_search'][box_idx] = state
        self._model.rr_state = rr_state

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=rubies_requested, type='custom')]
        )

