from pydantic import BaseModel  
from typing import List, Optional, Dict, Any  
from enum import Enum  
from abc import abstractmethod  

from system.message import Info  
from system.message import BaseMessageDataType  
from model.strategy_type import StrategyType  
from model.base import BaseStrategy  

class RubyRisksCustomStrategy:  
    def __init__(self, model: BaseStrategy):  
        self._model = model  
        self.name = self._model.name  
        self.history = self._model.history  
        self.strategy_type = StrategyType.Custom  

    def update_model_field(self, field_name: str, value: Any):  
        if hasattr(self._model, field_name):  
            setattr(self._model, field_name, value)  

    def receive_message(self, message: Info) -> Info:  
        data = message.message[0].data  
        total_rubies, current_turn, feedback, boxes = data  
        rubies_requested = None

        # Compute how many boxes have been opened so far (feedback > 0 for a new box opened)
        opened = 0
        remaining_rubies = total_rubies
        for f in feedback:
            if f > 0:
                opened += 1
                remaining_rubies -= f
            elif f == 0:
                # 0 means over-asked: we didn't open the next box (stay on same box)
                break

        boxes_left = boxes - opened
        # If only 1 box left, request all remaining rubies
        if boxes_left <= 1:
            rubies_requested = remaining_rubies
        else:
            # If previous feedback exists and last was 0, use previous guess - 1
            if feedback and feedback[-1] == 0:
                # Failed previous (overshot), so try less
                prev_guess = 0
                # Find last request made (assuming we always requested the same as previous box, unless adapted)
                if opened + len([f for f in feedback if f == 0]) == current_turn - 1:
                    # In sync: try previous guess minus one
                    if len(feedback) >= 2:
                        prev_guess = feedback[-2] if feedback[-2] > 0 else 1
                    else:
                        prev_guess = remaining_rubies // boxes_left
                else:
                    prev_guess = remaining_rubies // boxes_left
                rubies_requested = max(1, prev_guess - 1)
            else:
                # Estimate average for remaining boxes
                avg_guess = remaining_rubies // boxes_left
                rubies_requested = max(1, avg_guess)

        return Info(  
            sender=self.__class__.__name__,  
            receiver=message.sender,  
            difficulty=message.difficulty,  
            message=[BaseMessageDataType(data=rubies_requested, type='custom')]  
        )

